CREATE TABLE IF NOT EXISTS artemi_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artemi_nonces (id uuid PRIMARY KEY, wallet text NOT NULL, message text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS artemi_sessions (token_hash text PRIMARY KEY, wallet text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS artemi_rates (key text PRIMARY KEY, hits integer NOT NULL, resets_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS artemi_locations (id text PRIMARY KEY, name text NOT NULL, region text NOT NULL CHECK(region IN ('EU','US')), lat double precision NOT NULL, lng double precision NOT NULL, source text NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS artemi_uploads (id uuid PRIMARY KEY, wallet text NOT NULL, name text NOT NULL, ticker text NOT NULL, image text NOT NULL, uri text NOT NULL, twitter text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artemi_coins (mint text PRIMARY KEY, name text NOT NULL, ticker text NOT NULL, image text NOT NULL, uri text NOT NULL, creator text NOT NULL, twitter text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', treasury_amount numeric(30,0) NOT NULL, decimals integer NOT NULL, launch_signature text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artemi_bags (id uuid PRIMARY KEY, mint text NOT NULL REFERENCES artemi_coins(mint), location_id text NOT NULL REFERENCES artemi_locations(id), amount numeric(30,0) NOT NULL, status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','reserved','claimed')), claimant text, claim_signature text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS artemi_bags_mint_status ON artemi_bags(mint,status);
CREATE TABLE IF NOT EXISTS artemi_attempts (id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('launch','claim')), wallet text NOT NULL, mint text NOT NULL, bag_id uuid REFERENCES artemi_bags(id), status text NOT NULL CHECK(status IN ('prepared','queued','submitted','finalized','failed','expired')), message text NOT NULL, transaction_base64 text NOT NULL, signed_base64 text, signature text UNIQUE, last_valid_height bigint NOT NULL, payload jsonb NOT NULL, error text, tries integer NOT NULL DEFAULT 0, next_retry_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS artemi_one_active_claim ON artemi_attempts(bag_id) WHERE kind='claim' AND status IN ('prepared','queued','submitted','finalized');
CREATE INDEX IF NOT EXISTS artemi_attempts_wallet ON artemi_attempts(wallet,created_at DESC);
CREATE INDEX IF NOT EXISTS artemi_attempts_work ON artemi_attempts(status,next_retry_at);
CREATE TABLE IF NOT EXISTS artemi_worker_health (id integer PRIMARY KEY CHECK(id=1), heartbeat_at timestamptz NOT NULL, status text NOT NULL);
